initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStore = null;
  let orderingProduct = null;

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = `${store.店舗コード || ''} ${store.店舗名 || ''}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗しました:', error);
    }
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!currentStore) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      return;
    }

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数
      const predictedDemand = Math.floor(Math.random() * 50) + 5; // 仮の予測需要量
      const recommendedOrder = Math.max(0, predictedDemand - currentStock); // 推奨発注量

      return `
        <tr data-id="${product.id}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${currentStock}</td>
          <td style="text-align: right;">${predictedDemand}</td>
          <td style="text-align: right;">${recommendedOrder}</td>
          <td>
            <input type="number" 
                   class="input order-quantity" 
                   data-product-id="${product.id}"
                   value="${recommendedOrder}" 
                   min="0" 
                   style="width: 80px; text-align: right;">
          </td>
          <td>
            <input type="text" 
                   class="input order-reason" 
                   data-product-id="${product.id}"
                   placeholder="発注理由" 
                   style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${product.id}">発注</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.id}">調整</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 需要予測結果の表示
  function renderPredictionResults(storeId) {
    const predictionArea = container.querySelector('#prediction-area');

    if (!storeId) {
      predictionArea.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px;">店舗を選択すると需要予測結果が表示されます</div>';
      return;
    }

    // 仮の予測結果データ
    const totalPrediction = Math.floor(Math.random() * 1000) + 500;
    const accuracy = Math.floor(Math.random() * 20) + 80;

    predictionArea.innerHTML = `
      <div style="display: flex; gap: 24px; justify-content: center;">
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPrediction}</div>
          <div style="color: var(--text-muted); font-size: 14px;">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${accuracy}%</div>
          <div style="color: var(--text-muted); font-size: 14px;">予測精度</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${new Date().toLocaleDateString()}</div>
          <div style="color: var(--text-muted); font-size: 14px;">最終更新</div>
        </div>
      </div>
    `;
  }

  // 商品データの取得とフィルタリング
  async function loadAndFilterProducts() {
    try {
      const allProducts = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!allProducts) return;

      let filteredProducts = allProducts.filter(p => p.有効フラグ !== false);

      // カテゴリフィルタ
      const categoryFilter = container.querySelector('#category-select').value;
      if (categoryFilter) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品カテゴリ || '').includes(categoryFilter)
        );
      }

      // 商品名検索
      const searchKeyword = container.querySelector('#product-search').value.trim();
      if (searchKeyword) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品名 || '').includes(searchKeyword) || 
          (p.商品コード || '').includes(searchKeyword)
        );
      }

      currentProducts = filteredProducts;
      renderProducts(filteredProducts);
    } catch (error) {
      console.error('商品データの取得に失敗しました:', error);
    }
  }

  // 発注処理
  async function processOrder(productId) {
    const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
    const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

    const quantity = parseInt(quantityInput.value);
    const reason = reasonInput.value.trim();

    // バリデーション
    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      quantityInput.focus();
      return;
    }

    if (quantity < 0) {
      alert('発注量は正の数値を入力してください');
      quantityInput.focus();
      return;
    }

    if (quantity === 0) {
      alert('発注量は1以上を入力してください');
      quantityInput.focus();
      return;
    }

    if (!quantity) {
      alert('発注量を入力してください');
      quantityInput.focus();
      return;
    }

    const product = currentProducts.find(p => p.id === productId);
    if (!product) return;

    // 発注確認モーダルを表示
    const modal = container.querySelector('#order-modal');
    const content = container.querySelector('#order-confirm-content');

    content.innerHTML = `
      <div style="margin-bottom: 12px;"><strong>商品:</strong> ${product.商品名}</div>
      <div style="margin-bottom: 12px;"><strong>発注量:</strong> ${quantity}個</div>
      <div style="margin-bottom: 12px;"><strong>発注理由:</strong> ${reason || '(未入力)'}</div>
      <div style="margin-bottom: 12px;"><strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}</div>
    `;

    orderingProduct = { productId, quantity, reason, product };
    modal.classList.remove('hidden');
  }

  // 発注確定処理
  async function confirmOrder() {
    if (!orderingProduct) return;

    try {
      const orderData = {
        店舗ID: currentStore,
        商品ID: orderingProduct.productId,
        発注日: new Date().toISOString(),
        納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
        発注数量: orderingProduct.quantity,
        発注単価: orderingProduct.product.単価 || 0,
        発注金額: orderingProduct.quantity * (orderingProduct.product.単価 || 0),
        発注方法: orderingProduct.reason ? 'AI推奨修正' : 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: orderingProduct.product.仕入先ID || '',
        発注理由: orderingProduct.reason || '',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(7, orderData); // 発注データのインデックス

      if (saved) {
        alert('発注が完了しました');

        // 発注量と理由をクリア
        const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${orderingProduct.productId}"]`);
        const reasonInput = container.querySelector(`input.order-reason[data-product-id="${orderingProduct.productId}"]`);
        if (quantityInput) quantityInput.value = '0';
        if (reasonInput) reasonInput.value = '';
      } else {
        alert('発注処理に失敗しました');
      }
    } catch (error) {
      console.error('発注処理エラー:', error);
      alert('発注処理中にエラーが発生しました');
    }

    // モーダルを閉じる
    container.querySelector('#order-modal').classList.add('hidden');
    orderingProduct = null;
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const products = await window.aivicApi.list(2);
      if (!products || products.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['商品コード', '商品名', '商品カテゴリ', '単価', '販売価格', '発注単位', '最小発注数量', 'リードタイム日数'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...products.map(p => [
          p.商品コード || '',
          p.商品名 || '',
          p.商品カテゴリ || '',
          p.単価 || 0,
          p.販売価格 || 0,
          p.発注単位 || 1,
          p.最小発注数量 || 1,
          p.リードタイム日数 || 0
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `商品一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      alert('CSVエクスポートに失敗しました');
    }
  }

  // イベントリスナーの設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStore = e.target.value;
    renderPredictionResults(currentStore);
    if (currentStore) {
      loadAndFilterProducts();
    } else {
      renderProducts([]);
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    const dateStart = container.querySelector('#date-start').value;
    const dateEnd = container.querySelector('#date-end').value;

    // 日付バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    if (currentStore) {
      loadAndFilterProducts();
    }
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  // 商品テーブルのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      await processOrder(productId);
      return;
    }

    // 調整ボタン（推奨発注量を再設定）
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const currentStock = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock);
      quantityInput.value = recommendedOrder;
      return;
    }
  });

  // モーダルのイベントリスナー
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
    orderingProduct = null;
  });

  container.querySelector('#btn-confirm-order').addEventListener('click', confirmOrder);

  // 初期化処理
  loadStores();
  renderProducts([]);
  renderPredictionResults(null);
}
